-- Weekly consumables inventory alerts (Jira + Slack).
-- Apply to Supabase (SQL editor or migration runner) before using alerts in production.

CREATE TABLE IF NOT EXISTS "consumables_alert_batches" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "week_key" TEXT NOT NULL,
  -- submitted | empty_skipped
  "status" TEXT NOT NULL,
  "item_count" INTEGER NOT NULL DEFAULT 0,
  "out_of_stock_count" INTEGER NOT NULL DEFAULT 0,
  "below_minimum_count" INTEGER NOT NULL DEFAULT 0,
  "approaching_count" INTEGER NOT NULL DEFAULT 0,
  "good_count" INTEGER NOT NULL DEFAULT 0,
  "jira_issue_key" TEXT NOT NULL DEFAULT '',
  "jira_issue_url" TEXT NOT NULL DEFAULT '',
  "slack_channel_id" TEXT NOT NULL DEFAULT '',
  "slack_message_ts" TEXT NOT NULL DEFAULT '',
  "dry_run" BOOLEAN NOT NULL DEFAULT false,
  "error_message" TEXT NOT NULL DEFAULT '',
  "created_at" TIMESTAMPTZ DEFAULT now(),
  "submitted_at" TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX IF NOT EXISTS "consumables_alert_batches_week_key_uidx"
  ON "consumables_alert_batches" ("week_key");
